//
// Retail 0x007282A0 (821 bytes, ret 0x10): W3DTerrainBackground::
// setFlipRecursive, BFME's four-argument form. Identity: the matched setFlip
// wrapper at 0x00728BC0 calls it through ILT 0x0002E735, as does the body
// itself. The Zero Hour version flips a block when every height equals the
// corner; BFME instead predicts each height from the two corner triangles and
// flips when no sample strays past the float tolerance (the fourth stack word,
// compared with fcomp) and no cell is cliff-mapped. The last of the four
// recursive calls is a tail call VC7.1 turns into a jump back to the top.

typedef bool Bool;
typedef int Int;
typedef float Real;
typedef unsigned short UnsignedShort;

#define MAP_HEIGHT_SCALE 0.0390625f	// BFME; Zero Hour divided by 16

// upstream layout: inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngineDevice/Include/W3DDevice/GameClient/WorldHeightMap.h
class WorldHeightMap
{
public:
	Int getXExtent(void) const { return m_width; }
	Int getYExtent(void) const { return m_height; }
	UnsignedShort getHeight(Int xIndex, Int yIndex)
	{
		Int ndx = (yIndex * m_width) + xIndex;
		if ((ndx >= 0) && (ndx < m_dataSize) && m_data)
			return m_data[ndx];
		return 0;
	}
	Bool isCliffMappedTexture(Int x, Int y)
	{
		Int ndx = (m_drawOriginY + y) * m_width + m_drawOriginX + x;
		if (ndx < 0 || ndx >= m_dataSize)
			return false;
		return m_cliffInfo[ndx] != 0;
	}

	void *m_vtable;
	Int m_refs;						// +0x04
	Int m_width;					// +0x08
	Int m_height;					// +0x0c
	unsigned char m_pad10[0x20 - 0x10];
	Int m_dataSize;					// +0x20
	UnsignedShort *m_data;			// +0x24
	unsigned char m_pad28[0x94 - 0x28];
	void **m_cliffInfo;				// +0x94
	unsigned char m_pad98[0x120e0 - 0x98];
	Int m_drawOriginX;				// +0x120E0
	Int m_drawOriginY;				// +0x120E4
};

// The matched setFlipState body (retail 0x00749830, ILT 0x0003F7C4) carries
// this address-derived spelling in the ledger.
class BfmeMaskAX
{
public:
	void bfmeMarkAX(Int x, Int y, unsigned char value);
};

// upstream layout: inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngineDevice/Include/W3DDevice/GameClient/W3DTerrainBackground.h
class W3DTerrainBackground
{
protected:
	void setFlipRecursive(Int xOffset, Int yOffset, Int width, Real tolerance);

	unsigned char m_pad00[0x40];
	Int m_xOrigin;					// +0x40
	Int m_yOrigin;					// +0x44
	Int m_width;					// +0x48
	WorldHeightMap *m_map;			// +0x4c
};

void W3DTerrainBackground::setFlipRecursive(Int xOffset, Int yOffset, Int width, Real tolerance)
{
	Int limitX = m_map->getXExtent() - 1;
	Int limitY = m_map->getYExtent() - 1;
	Int i, j;
	Bool match = true;
	Int minX = m_xOrigin + xOffset;
	Int minY = m_yOrigin + yOffset;
	Int maxX = minX + width;
	maxX = maxX < limitX ? maxX : limitX;
	Int maxY = minY + width;
	maxY = maxY < limitY ? maxY : limitY;
	Int h00 = m_map->getHeight(minX, minY);
	Int h10 = m_map->getHeight(maxX, minY);
	Int h11 = m_map->getHeight(maxX, maxY);
	Int h01 = m_map->getHeight(minX, maxY);

	for (i = 0; i <= width; i++) {
		for (j = 0; j <= width; j++) {
			Int k = minX + i;
			k = k < limitX ? k : limitX;
			Int l = minY + j;
			l = l < limitY ? l : limitY;
			if (m_map->isCliffMappedTexture(k, l)) {
				match = false;
				break;
			}
			Real fx = (Real)i / width;
			Real fy = (Real)j / width;
			Real height;
			if (fy > 1.0f - fx) {
				height = ((h10 - h11) * (1.0f - fy) + (h01 - h11) * (1.0f - fx) + h11) * MAP_HEIGHT_SCALE;
			} else {
				height = (fy * (h01 - h00) + (h10 - h00) * fx + h00) * MAP_HEIGHT_SCALE;
			}
			Real delta = height - m_map->getHeight(k, l) * MAP_HEIGHT_SCALE;
			if (delta < 0.0f)
				delta = -delta;
			if (delta > tolerance) {
				match = false;
				break;
			}
		}
	}
	if (width == 1 || match) {
		maxX = minX + width;
		maxX = maxX < limitX ? maxX : limitX;
		maxY = minY + width;
		maxY = maxY < limitY ? maxY : limitY;
		((BfmeMaskAX *)m_map)->bfmeMarkAX(minX, minY, true);
		((BfmeMaskAX *)m_map)->bfmeMarkAX(maxX, minY, true);
		((BfmeMaskAX *)m_map)->bfmeMarkAX(maxX, maxY, true);
		((BfmeMaskAX *)m_map)->bfmeMarkAX(minX, maxY, true);
		return;
	}
	Int halfWidth = width / 2;

	setFlipRecursive(xOffset, yOffset, halfWidth, tolerance);
	setFlipRecursive(xOffset, yOffset + halfWidth, halfWidth, tolerance);
	setFlipRecursive(xOffset + halfWidth, yOffset, halfWidth, tolerance);
	setFlipRecursive(xOffset + halfWidth, yOffset + halfWidth, halfWidth, tolerance);
}
